import{_ as p,C as o,o as g,c as h,a2 as r,E as a,w as i,a as n,j as e}from"./chunks/framework.CHeM0PsO.js";const T=JSON.parse('{"title":"后肠发酵与长纤维","description":"兔的后肠发酵原理、结肠颗粒分选系统，以及为什么\\"长纤维牧草\\"不可替代——颗粒粮、粉末化饲料无法提供维持蠕动所需的物理刺激。","frontmatter":{"title":"后肠发酵与长纤维","description":"兔的后肠发酵原理、结肠颗粒分选系统，以及为什么\\"长纤维牧草\\"不可替代——颗粒粮、粉末化饲料无法提供维持蠕动所需的物理刺激。","lastReviewed":"2026-07-27T00:00:00.000Z"},"headers":[],"relativePath":"digest/hindgut-fermentation.md","filePath":"digest/hindgut-fermentation.md","lastUpdated":null}'),m={name:"digest/hindgut-fermentation.md"};function c(f,t,b,_,q,S){const l=o("Warning"),d=o("Info"),s=o("SourceCard"),u=o("SourceList");return g(),h("div",null,[t[6]||(t[6]=r(`<h1 id="🌿-后肠发酵与长纤维" tabindex="-1">🌿 后肠发酵与长纤维 <a class="header-anchor" href="#🌿-后肠发酵与长纤维" aria-label="Permalink to &quot;🌿 后肠发酵与长纤维&quot;">​</a></h1><p>上一节讲了盲肠是&quot;发酵罐&quot;。本节回答一个核心问题：<strong>为什么必须给兔吃&quot;长&quot;牧草，颗粒粮不能代替？</strong></p><p>答案在于兔结肠里的一套精巧的<strong>颗粒分选系统</strong>。</p><h2 id="一、后肠发酵-hindgut-fermentation-原理" tabindex="-1">一、后肠发酵（Hindgut Fermentation）原理 <a class="header-anchor" href="#一、后肠发酵-hindgut-fermentation-原理" aria-label="Permalink to &quot;一、后肠发酵（Hindgut Fermentation）原理&quot;">​</a></h2><p>兔的前段消化（胃、小肠）与其他单胃哺乳动物相似——用酶消化简单蛋白和碳水化合物。但<strong>纤维素的最终分解发生在盲肠</strong>，这就是&quot;后肠&quot;发酵的含义<cite><a href="#ref1">[1]</a></cite>。</p><p>发酵产物——<strong>挥发性脂肪酸（VFA）</strong>——经盲肠壁吸收，提供兔<strong>约 40% 的维持能量</strong><cite><a href="#ref2">[2]</a></cite>。</p><h2 id="二、结肠的颗粒分选系统-关键" tabindex="-1">二、结肠的颗粒分选系统（关键） <a class="header-anchor" href="#二、结肠的颗粒分选系统-关键" aria-label="Permalink to &quot;二、结肠的颗粒分选系统（关键）&quot;">​</a></h2><p>兔结肠有一套<strong>机械颗粒分选系统</strong>，这是理解&quot;为什么长纤维不可替代&quot;的核心<cite><a href="#ref1">[1]</a></cite>：</p><ul><li>结肠壁的囊状结构（haustra）<strong>反向推送小颗粒（&lt;0.3 mm）回到盲肠</strong>继续发酵</li><li><strong>大颗粒（&gt;0.3 mm，尤其 &gt;0.5 mm 的木质化纤维）被正向推送</strong>，作为硬粪排出</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>食糜进入结肠</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ├─ 小颗粒 (&lt;0.3 mm) ──→ 反向推送回盲肠 ──→ 继续发酵 ──→ 产生 VFA</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     └─ 大颗粒 (&gt;0.5 mm)  ──→ 正向推送 ──→ 形成硬粪排出</span></span></code></pre></div><h2 id="三、纤维的两种功能-教科书级分类" tabindex="-1">三、纤维的两种功能（教科书级分类） <a class="header-anchor" href="#三、纤维的两种功能-教科书级分类" aria-label="Permalink to &quot;三、纤维的两种功能（教科书级分类）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>颗粒大小</th><th>营养价值</th><th>物理作用</th></tr></thead><tbody><tr><td><strong>不可消化纤维（粗长木质化颗粒 &gt;0.5 mm）</strong></td><td>大</td><td>无直接营养</td><td><strong>刺激肠道蠕动</strong>——这是&quot;长纤维&quot;不可替代的物理作用</td></tr><tr><td><strong>可发酵纤维（小颗粒，半纤维素/纤维素）</strong></td><td>小</td><td>进入盲肠发酵产 VFA</td><td>提供能量</td></tr></tbody></table>`,12)),a(l,{title:"为什么颗粒粮和粉末化牧草不能替代长牧草"},{default:i(()=>[...t[0]||(t[0]=[n(' 如果纤维被磨得过细（如过多的颗粒粮、粉末化牧草、磨碎的草饼）： 1. 大颗粒（>0.5 mm）不足 → **结肠分选失效** 2. 盲肠内容物过度潴留 → "食糜堵塞（chymus jam）" 3. 发酵失衡，pH 偏移 → **致病菌（如 *Clostridium*）增殖** ',-1),e("p",null,[n("颗粒粮的热量、维生素可以做到和牧草一样，但"),e("strong",null,'它无法提供刺激肠道蠕动所需的"长纤维"物理刺激'),n('。这就是为什么"无限量供应长牧草"是兔饲养的第一法则，没有例外'),e("cite",null,[e("a",{href:"#ref1"},"[1]")]),n("。")],-1)])]),_:1}),t[7]||(t[7]=r('<h2 id="四、这个机制和-胃肠停滞-gi-stasis-的关系" tabindex="-1">四、这个机制和&quot;胃肠停滞（GI Stasis）&quot;的关系 <a class="header-anchor" href="#四、这个机制和-胃肠停滞-gi-stasis-的关系" aria-label="Permalink to &quot;四、这个机制和&quot;胃肠停滞（GI Stasis）&quot;的关系&quot;">​</a></h2><p>理解了颗粒分选，就理解了 GI Stasis 的核心驱动机制<cite><a href="#ref1">[1]</a></cite><cite><a href="#ref3">[3]</a></cite>：</p><ol><li>正常肠蠕动的<strong>主要驱动力是大量不可消化纤维的存在</strong></li><li>纤维不足或厌食 → 蠕动障碍</li><li>蠕动停止 → 胃液被持续吸收 → 内容物脱水压实 → <strong>疼痛</strong></li><li>疼痛 → 进一步厌食（<strong>恶性循环</strong>）</li><li>盲肠排空变慢 → <em>Clostridium</em> 等致病菌快速增殖 → 产气（胀气、剧痛）+ 释放致命毒素</li></ol><p><strong>这就是为什么&quot;换粮&quot;&quot;突然减少牧草&quot;&quot;应激拒食&quot;能在 12 小时内演变成致命急症。</strong></p>',4)),a(d,{title:"最新研究：菌群变化是『原因』还是『结果』？（诚实标注的争议）"},{default:i(()=>[...t[1]||(t[1]=[n(" 2025 年 PLOS ONE 一项对 43 只兔（21 健康 + 22 GI Stasis）粪便微生物组的研究发现，停滞组中 *Clostridium sensu stricto 1* 和某种肠杆菌科细菌增多，5 个有益菌属减少",-1),e("cite",null,[e("a",{href:"#ref4"},"[4]")],-1),n("。 ",-1),e("p",null,[e("strong",null,'但研究作者明确指出：目前无法确定这些菌群变化是 GI Stasis 的"原因"还是"后果"。'),n(" 这是兽医学界正在研究的前沿问题，本站如实标注，不替读者下结论。")],-1)])]),_:1}),t[8]||(t[8]=r('<h2 id="五、实操结论" tabindex="-1">五、实操结论 <a class="header-anchor" href="#五、实操结论" aria-label="Permalink to &quot;五、实操结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>✅ 应该做</th><th>❌ 不应该做</th></tr></thead><tbody><tr><td>成兔<strong>无限量</strong>供应提摩西草/果园草等长禾本科牧草</td><td>用颗粒粮&quot;代替&quot;牧草</td></tr><tr><td>选<strong>第一、二茬</strong>带茎的提摩西草（颗粒大、纤维长）</td><td>只喂柔软多叶的第三茬（纤维不足）</td></tr><tr><td>颗粒粮按体重限量（成兔每 2.25 kg 约 1/8–1/4 杯/天）</td><td>把颗粒粮当主食</td></tr><tr><td>提供多种禾本科牧草（果园草、燕麦草）增加多样性</td><td>喂大量水果、淀粉、面包等高碳水零食</td></tr><tr><td>每天观察粪便量和形状</td><td>忽视&quot;粪便变小、变少&quot;的早期信号</td></tr></tbody></table><p>详细的牧草选择、品质鉴别、各阶段配比，见<a href="./../supplies/hay/">常备药与用品 → 牧草专题</a>。</p>',3)),a(u,null,{default:i(()=>[t[2]||(t[2]=e("p",null,[e("a",{id:"ref1"})],-1)),a(s,{title:"Digestive problems in rabbit production: moving in the wrong direction",author:"van der Sluis M et al. (2024), Frontiers in Veterinary Science",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC10879550/",accessed:"2026-07-27",level:"vet",note:"颗粒分选系统（>0.3 mm / >0.5 mm 阈值）、chymus jam 概念、纤维功能分类。"}),t[3]||(t[3]=e("p",null,[e("a",{id:"ref2"})],-1)),a(s,{title:"Digestive Disorders of Rabbits",author:"Varga M (2013), Textbook of Rabbit Medicine",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC7149685/",accessed:"2026-07-27",level:"vet",note:"VFA 提供约 40% 维持能量；盲肠发酵机制教科书级陈述。"}),t[4]||(t[4]=e("p",null,[e("a",{id:"ref3"})],-1)),a(s,{title:"Gastrointestinal Diseases of Rabbits",author:"Oglesbee BL & Lord B (2020)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC7258705/",accessed:"2026-07-27",level:"vet",note:"GI Stasis 由低纤维/应激/疼痛诱发；恶性循环机制。"}),t[5]||(t[5]=e("p",null,[e("a",{id:"ref4"})],-1)),a(s,{title:"Effect of rabbit gastrointestinal stasis (RGIS) on the fecal microbiota",author:"Rahic-Seggerman FM et al. (2025), PLOS ONE",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0318810",accessed:"2026-07-27",level:"vet",note:"首项 RGIS 粪便微生物组系统研究（n=43）。作者明确说明菌群变化因果未定。"})]),_:1})])}const C=p(m,[["render",c]]);export{T as __pageData,C as default};
